CREATE TABLE "background_jobs" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "queue" TEXT NOT NULL,
    "job_type" TEXT NOT NULL,
    "data" TEXT NOT NULL,
    "retries" INTEGER NOT NULL,
    "priority" SMALLINT NOT NULL,
    "run_at" TIMESTAMPTZ(6) NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "locked_until" TIMESTAMPTZ(6),
    "locked_by" TEXT,
    "failed_at" TIMESTAMPTZ(6),
    PRIMARY KEY ("id")
);
CREATE INDEX "index_background_jobs_poll" ON "background_jobs" ("queue", "failed_at", "locked_until", "run_at");
CREATE TABLE "rate_limit_buckets" (
    "bucket_key" TEXT NOT NULL,
    "action" TEXT NOT NULL,
    "bucket_id" TEXT NOT NULL,
    "tokens" INTEGER NOT NULL,
    "last_refill" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("bucket_key")
);
CREATE TABLE "users" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "provider" TEXT NOT NULL,
    "provider_user_id" TEXT NOT NULL,
    "login" TEXT NOT NULL,
    "name" TEXT,
    "email" TEXT,
    "avatar_url" TEXT,
    "is_active" BOOLEAN NOT NULL,
    "account_lock_reason" TEXT,
    "account_lock_until" TIMESTAMPTZ(6),
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_users_by_provider_and_provider_user_id" ON "users" ("provider", "provider_user_id");
CREATE TABLE "api_tokens" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "name" TEXT NOT NULL,
    "token" BYTEA NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "last_used_at" TIMESTAMPTZ(6),
    "revoked" BOOLEAN NOT NULL,
    "resource_scopes" TEXT,
    "action_scopes" TEXT,
    "expired_at" TIMESTAMPTZ(6),
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "index_api_tokens_by_token" ON "api_tokens" ("token");
CREATE TABLE "posts" (
    "id" BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" BIGINT NOT NULL,
    "title" TEXT NOT NULL,
    "content" TEXT NOT NULL,
    "published" BOOLEAN NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    PRIMARY KEY ("id")
);
CREATE INDEX "index_posts_by_user_id" ON "posts" ("user_id");
